    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  CLIENT\n  ADMIN\n}\n\nenum InquiryStatus {\n  PENDING\n  APPROVED\n  ORDERED\n  REVIEWED\n  COMPLETED\n  CANCELLED\n}\n\nmodel User {\n  id          String    @id @default(cuid())\n  phone       String    @unique\n  name        String\n  password    String?\n  email       String?   @unique\n  address     String?\n  city        String?   @default(\"Dhaka\")\n  avatar      String?\n  selfieImage String?\n  verified    Boolean   @default(false)\n  verifiedAt  DateTime?\n  role        Role      @default(CLIENT)\n  canReview   Boolean   @default(false)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  chatMessages ChatMessage[]\n  inquiries    Inquiry[]\n  reviews      Review[]\n\n  @@map(\"users\")\n}\n\nmodel EmailOtp {\n  id        String   @id @default(cuid())\n  email     String\n  code      String\n  type      String // \"REGISTER\" | \"FORGOT_PASSWORD\"\n  data      String?\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@index([email, type])\n  @@map(\"email_otps\")\n}\n\nmodel Product {\n  id               String   @id\n  title            String\n  description      String\n  category         String\n  subCategory      String?\n  price            Float    @default(0)\n  originalPrice    Float\n  commission       String?\n  commissionAmount Float    @default(0)\n  image            String\n  gallery          String[] @default([])\n  affiliateCode    String?\n  features         String[] @default([])\n  rating           Float    @default(5.0)\n  reviewsCount     Int      @default(0)\n  badge            String?\n  inStock          Boolean  @default(true)\n  store            String?\n  amazonUrl        String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  inquiries Inquiry[]\n  reviews   Review[]\n\n  @@map(\"products\")\n}\n\nmodel ChatMessage {\n  id           String   @id @default(cuid())\n  sender       String // \"customer\" | \"admin\"\n  senderName   String?\n  text         String\n  image        String?\n  productId    String?\n  productTitle String?\n  productPrice Float?\n  productImage String?\n  read         Boolean  @default(false)\n  userId       String?\n  user         User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  createdAt    DateTime @default(now())\n\n  @@map(\"chat_messages\")\n}\n\nmodel Inquiry {\n  id            String        @id @default(cuid())\n  userId        String\n  user          User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId     String\n  product       Product       @relation(fields: [productId], references: [id], onDelete: Cascade)\n  status        InquiryStatus @default(PENDING)\n  amazonOrderId String?\n  reviewUrl     String?\n  notes         String?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  @@map(\"inquiries\")\n}\n\nmodel Review {\n  id        String   @id @default(cuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userName  String\n  rating    Int      @default(5)\n  title     String?\n  comment   String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([productId])\n  @@index([userId])\n  @@map(\"reviews\")\n}\n",
